function applyState(data){state.snapshotEpoch++;const previousStudy=state.lab?.queue;if(data.csrf)state.csrf=data.csrf;if(data.catalog){state.catalog=data.catalog;render?.setCatalog(data.catalog)}if(data.serverTime){state.serverOffset=data.serverTime-Date.now()/1000;render?.setServerTime(data.serverTime);}if(data.user!==undefined)state.user=data.user;for(const k of ['base','army','queue','research','researchQueue','unlocked','unlockQueue','garrison','lab','activeBattle'])if(data[k]!==undefined)state[k]=data[k];if(previousStudy&&data.lab&&!data.lab.queue&&(data.lab.levels?.[previousStudy.type]||0)>=previousStudy.target_level){audio.effect('research');toast(`${state.catalog.labAbilities?.[previousStudy.type]?.name||'Lab ability'} tier ${previousStudy.target_level} is ready.`);}if(data.world){state.world=data.world;$('#bot-count').textContent=num(data.world.bots);worldActivity.observe(data.world.activity);}if(state.user){$('#player-name').textContent=state.user.name;$('#player-rank').textContent=`${num(state.user.rank_points)} rank points`;$('#rank-score').textContent=num(state.user.rank_points);renderResources();if(!state.visiting&&!state.battle&&!planner.active()){render.setBase({...state.base,army:state.army});if(state.selected?.decoration)state.selected=decorationSelection(state.base.decorations?.find(p=>p.id===state.selected.pieceId))||null;else if(state.selected)state.selected=state.base.buildings.find(b=>b.id===state.selected.id)||null;render.setSelected(state.selected)}if(state.battle?.training && !state.battle?.infernoDefense && data.base && (state.activeBattle || data.base.baiter?.session?.id !== baiter.currentId()))leaveDrill();
if(data.base){const count=data.base.truceOffers||0;$('#truce-button-label').textContent=count?`Truces (${count} pending)`:'Truces';}if(state.modal==='baiter')baiter.refreshEditor();if(state.modal==='season'||state.modal==='emergence')baiter.refreshSeason();renderArmy();updateYardHeading();if(planner.active())planner.sync();else renderPanel();workers.refresh();mushrooms.refresh();siegeWorkshop.refresh();}quests.refresh();worldActivity.sync();}
async function refresh({resume=true,territory=true}={}){if(refreshBusy)return;const token={epoch:state.snapshotEpoch,owner:state.user?.id};const current=()=>token.epoch===state.snapshotEpoch&&token.owner===state.user?.id;refreshBusy=true;try{const data=await api('bootstrap');if(!current())return;applyState(data);if(!data.user){resetAccount();showAuth();return}if(resume&&data.activeBattle&&!state.battle&&!state.dismissedBattles.has(data.activeBattle.id)){await openBattle(data.activeBattle.id)}workshop.refresh();championHall.refresh();laboratory.refresh();fortifications.refresh();if(territory){await territories.refresh();await inferno.refresh();}}catch(e){toast(e.message,true)}finally{refreshBusy=false}}
// Mutations must not reuse a bootstrap that began before they committed.
async function synchronizeHome(){
 const owner=state.user?.id,navigation=state.navigationEpoch,battle=state.battleEpoch;
 const current=()=>!!owner&&owner===state.user?.id&&navigation===state.navigationEpoch&&battle===state.battleEpoch;
 // Invalidate pre-commit reads once. Retrying must not invalidate other synchronizers.
 if(current())state.snapshotEpoch++;
 while(current()){
  const epoch=state.snapshotEpoch,data=await api('bootstrap');
  if(!current())return;
  if(epoch!==state.snapshotEpoch)continue;
  applyState(data);
  if(!data.user){resetAccount();showAuth();return}
  if(data.activeBattle&&!state.battle&&!state.dismissedBattles.has(data.activeBattle.id))await openBattle(data.activeBattle.id);
  workshop.refresh();championHall.refresh();laboratory.refresh();fortifications.refresh();return;
 }
}
