 const cavern=underground?inferno.snapshot():null;
 const stores=state.battle?.infernoStores||(cavern&&{resources:cavern.base.resources,capacity:cavern.capacity});
 const resources=underground?stores?.resources||{}:state.base?.resources||{},cap=underground?stores?.capacity||1:state.base?.capacity||1;
 const keys=underground?['bone','coal','sulfur','magma']:['twig','pebble','putty','goo'];
 const labels={twig:'TWIGS',pebble:'PEBBLES',putty:'PUTTY',goo:'GOO',bone:'BONE',coal:'COAL',sulfur:'SULFUR',magma:'MAGMA'};
