 $('#resources').innerHTML=keys.map(key=>`<div class="resource ${underground?'inferno-':''}${key}" title="${num(resources[key])} / ${num(cap)} storage"><span class="resource-icon">${icon(symbols[key]||key)}</span><div><div class="resource-top"><span>${labels[key]}</span></div><b>${underground&&!stores?'—':num(resources[key])}</b><div class="resource-track"><i style="width:${Math.min(100,100*(resources[key]||0)/cap)}%"></i></div></div></div>`).join('')
