async function setPage(page){if(state.battle?.status==='active'&&page!=='yard'){toast('Finish the current battle before leaving the battlefield.');return}navigationIntent();state.page=page;if(state.user){renderResources();if(state.visiting?.realm==='inferno'&&!state.battle)audio.playMusic(page==='yard'?'inferno':'theme');}repairs.refresh();window.scrollTo({top:0,behavior:'instant'});$$('.page').forEach(el=>el.hidden=el.id!==`page-${page}`);$$('.nav-item').forEach(el=>el.classList.toggle('active',el.dataset.page===page));worldMap.setVisible(page==='world');if(page==='world')await worldMap.open();if(page==='yard'){requestAnimationFrame(()=>render.resize())}if(page==='invasion')await loadRivals();if(page==='rankings')await loadRankings();if(page==='reports')await loadReports();}
