async function place(pos,p){
 if(p.realm==='mr2'){await territories.placeOutpost(pos,p);return;}
 if(p.realm==='inferno'){await inferno.place(pos,p);return;}
 if(p.mode==='yardSign'){await yardMessages.place(pos,p);return;}
 if(p.mode==='decoration'){await decorations.place(pos,p);return;}
 if(planner.place(pos,p))return;
 if(p.mode==='siege'){await siegeCombat.fire(pos,p);return;}
 if(p.mode==='catapult'){
  if(state.battleBusy||state.battle?.status!=='active')return;
  state.battleBusy=true;
  try{const battle=await api('catapult',{battleId:state.battle.id,type:p.type,level:p.level,...pos});updateBattle(battle);if(battle.status==='active')restoreBucketAim();toast('Catapult launched. This resource family is spent for this invasion.');}
  catch(e){toast(e.message,true)}finally{state.battleBusy=false}return;
 }
 if(p.mode==='champion'){if(state.battleBusy||state.battle?.status!=='active')return;state.battleBusy=true;try{const battle=await api('deployChampion',{battleId:state.battle.id,...pos,...(p.type==='krallen'?{type:'krallen'}:{})});cancelPlacement();updateBattle(battle);toast(p.type==='krallen'?'Krallen has entered the battle.':'Your champion has entered the battle.')}catch(e){toast(e.message,true)}finally{state.battleBusy=false}return;}
 if(p.mode==='deploy'){
  if(state.battleBusy||!state.battle||state.battle.status!=='active')return;
  if(bucketCooldown()>0){toast('The Flinger is reloading. Your bucket is still selected.');return}
  const troops={...state.bucket};if(!Object.keys(troops).length)return;
  state.battleBusy=true;
  try{const battle=await api('deploy',{battleId:state.battle.id,troops,...pos});state.bucket={};cancelPlacement();updateBattle(battle);audio.effect('fling');toast('Bucket launched. Load your next wave.')}catch(e){toast(e.message,true)}finally{state.battleBusy=false}return;
 }
 const data=await action(p.mode==='move'?'move':'build',{type:p.type,id:p.id,...pos});if(data){audio.effect('build');toast(p.mode==='move'?'Building moved.':'Construction started.');cancelPlacement();state.selected=null;render.setSelected(null);renderPanel();}
}
function readyChampion(){const type=state.base?.activeChampion,c=state.base?.champions?.[type];return c&&c.hp>0&&!c.frozen&&!c.battle_id&&(state.base.buildings||[]).some(b=>b.type==='championcage'&&b.level>0&&b.hp>0&&b.ready_at<=now())?{...c,type}:null;}
function championDeploymentHTML(){const c=state.battle?.champion;if(!c)return '';const spec=state.catalog.champions?.[c.type];if(!spec)return '';return `<div class="champion-deploy-panel"><div>${art(c.type+'-e'+(c.level||1),spec.name)}<span><b>${esc(spec.name)}</b><small>Evolution ${c.level}${c.bonus_feeds?` · Bonus ${c.bonus_feeds}`:''} · ${num(c.hp)} HP</small></span></div><button class="button subtle block" data-command="deploy-champion" ${!c.available||c.deployed?'disabled':''}>${c.deployed?'Champion deployed':c.available?'Deploy '+esc(spec.name):'Champion unavailable'}</button><p class="subtle-note">One deployment. Separate from the Flinger bucket.</p></div>`;}
function hasFlinger(){return (state.base?.buildings||[]).some(b=>b.type==='flinger'&&b.level>0&&b.hp>0&&b.ready_at<=now())}
function deploymentSlots(){
 const used=(state.battle?.units||[]).filter(unit=>unit.team!=='defender'&&!unit.champion&&!unit.summoned).length;
 return Math.max(0,(state.battle?.flinger?.unitLimit??200)-used);
}
function bucketCount(){return Object.values(state.bucket).reduce((a,b)=>a+b,0)}
function bucketSpace(type){return state.battle?.flinger?.weights?.[type] ?? state.catalog.monsters[type]?.size ?? 0}
function bucketWeight(){return Object.entries(state.bucket).reduce((sum,[key,count])=>sum+count*bucketSpace(key),0)}
function bucketCooldown(){if(!state.battle?.flinger)return 0;const elapsed=state.battle.elapsed+Math.min(2,(performance.now()-(state.battleReceivedAt||performance.now()))/1000);return Math.max(0,state.battle.flinger.readyAt-elapsed)}
function bucketHTML(){
 const cap=state.battle.flinger?.capacity||100,weight=bucketWeight(),wait=bucketCooldown();
 return `<div class="flinger-bucket"><div class="bucket-heading"><b>Flinger bucket${state.battle.flinger?.level?' · Lv '+state.battle.flinger.level:''}</b><span>${weight} / ${cap}</span></div><div class="progress-bar"><i style="width:${Math.min(100,weight/cap*100)}%"></i></div><div class="bucket-contents">${Object.entries(state.bucket).map(([key,count])=>`<div>${art(key,'')}<span>${esc(state.catalog.monsters[key].name)} <b>×${count}</b></span><button class="icon-button" data-bucket-remove="${key}" aria-label="Remove one ${esc(state.catalog.monsters[key].name)} from bucket">${icon('minus')}</button></div>`).join('')||'<p>Click monsters below to add them.</p>'}</div><div class="bucket-ready" id="bucket-cooldown">${wait>0?'Reloading · '+duration(wait):'Ready to launch'}</div>${weight?'<button class="button subtle small block" data-command="clear-bucket">Empty bucket</button>':''}<p class="subtle-note">${state.battle.flinger?.weights?'Aim the ring on clear ground. Loads above 800 space need a wider landing zone.':'Click clear ground to launch.'} Monsters remain yours until launched.</p></div>`;
}
function adjustBucket(type,delta){
 if(!state.battle||state.battle.status!=='active'||state.battle.attacker.id!==state.user.id)return;
 const current=state.bucket[type]||0,next=Math.max(0,current+delta),size=bucketSpace(type),cap=state.battle.flinger?.capacity||100;
 if(delta>0&&bucketCount()+delta>deploymentSlots()){toast('This invasion has no room for another monster in this bucket.');return}
 if(next>(state.battle.remaining[type]||0)){toast('All ready monsters of this species are already in the bucket.');return}
 if(bucketWeight()+delta*size>cap){toast('The bucket is full. Launch it, remove a monster, or upgrade your Flinger.');return}
 if(next)state.bucket[type]=next;else delete state.bucket[type];
 const first=Object.keys(state.bucket)[0];if(first)choosePlacement({mode:'deploy',type:first});else cancelPlacement();renderPanel();
}

