function closeModal(){if(state.modal==='auth'&&!state.user)return;state.modalEpoch++;if(state.modal==='fortification-cancel')fortifications.reset();if(state.modal?.startsWith('territory'))territories.cancelPending();$('#modal').hidden=true;$('#app').inert=false;state.modal=null;$('#modal-body').innerHTML='';if(modalFocus?.isConnected)modalFocus.focus();else $('#hatchery-open')?.focus();}
