function presentDrill(battle, entering) {
 if (entering) {
   navigationIntent(); state.battleEpoch++; cancelPlacement(); state.selected=null;
   render.setSelected(null); render.resetCamera();
   if (battle.status==='active') battlefieldMusic(battle);
 }
 state.battle=battle; state.battleReceivedAt=performance.now();
 render.setBattle(battle); renderArmy(); renderPanel(); updateYardHeading();
 $('#battle-timer').textContent=duration(Math.max(0,battle.duration-battle.elapsed));
 $('#battle-destruction').textContent=`${num(battle.result?.destruction??battle.destruction??0)}% ${battle.molochStage||battle.emergenceStage||battle.wmiStage||battle.blitzStage||battle.brukkargStage||battle.horse?'yard':'drill'} damage`;
 $('#battle-result').hidden=battle.status!=='finished';
 if(battle.status==='finished'){ $('#battle-result').innerHTML=baiter.result(battle); audio.playMusic('theme'); }
}
function leaveDrill() {
 if(!state.battle?.training)return;
 const settledEvent = state.battle.status === 'finished' && (state.battle.molochStage || state.battle.emergenceStage || state.battle.wmiStage || state.battle.blitzStage || state.battle.brukkargStage || state.battle.horse);
 baiter.reset(); state.battleEpoch++; state.snapshotEpoch++; state.battle=null;
 render.setBattle(null); render.setBase({...state.base,army:state.army}); render.resetCamera();
 $('#battle-result').hidden=true; renderArmy(); updateYardHeading(); renderPanel(); audio.playMusic('theme');
 if (settledEvent) void refresh({resume:false,territory:false});
}
